import json,subprocess,concurrent.futures
runners=['trail-review','trail-confidence','trail-drift','trail-risk','trail-security','trail-semantic-diff','trail-summary']
def get(r):
 x=json.loads(subprocess.check_output(['entire','api','--to','cell',f'/api/v1/trails/gh/entireio/entire-graph/159/runs/{r}'])); return r,x
for r,x in concurrent.futures.ThreadPoolExecutor().map(get,runners):
 run=x.get('run') or {};print(r,run.get('status'),run.get('headSha'),json.dumps(x.get('result'))[:2300])
PY",max_output_tokens:4500}));
